package app.planaloud;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.util.*;
import android.widget.*;
import androidx.core.graphics.PathParser;
import org.json.*;
import org.xmlpull.v1.XmlPullParser;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** Named local background assets; records refer to stable IDs instead of local file paths. */
final class CardBackgrounds {
    static final int PICK=125;
    static final String[] BUILTIN={"color","wallpaper","svg:waves","svg:orbit","svg:geo","motion:aurora","motion:ripple","motion:stars","motion:rainbow","motion:meteors","motion:prism","motion:gold","motion:violet"};
    static final String[] NAMES={"自动事件配色","跟随主界面壁纸","SVG · 柔和波浪","SVG · 圆环星轨","SVG · 几何拼色","动态 · 极光","动态 · 涟漪","动态 · 星点","动态 · 彩虹模糊渐变","动态 · 流星","动态 · 淡棱彩","动态 · 柔金光","动态 · 柔紫光"};
    static final ExecutorService worker=Executors.newSingleThreadExecutor();private static final Set<String> loading=new HashSet<>(),failed=new HashSet<>();private static final Map<String,Set<Runnable>> waiters=new HashMap<>();private static File wallpaper;private static long wallpaperAt=-10000;private static final android.util.LruCache<String,Bitmap> cache=new android.util.LruCache<>(8*1024*1024){protected int sizeOf(String k,Bitmap v){return v.getAllocationByteCount();}};
    private static final Map<String,Picture> vectors=new HashMap<>();
    private static File folder(Context c){File dir=new File(c.getFilesDir(),"card-backgrounds");dir.mkdirs();return dir;}
    static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("settings",0);}
    static synchronized JSONArray list(Context c){try{AtomicFile f=new AtomicFile(new File(folder(c),"index.json"));if(!f.getBaseFile().isFile())return new JSONArray();try(InputStream in=f.openRead()){return new JSONArray(MarkdownFiles.read(in));}}catch(Exception e){Diagnostics.record(c,"card-backgrounds",e);return new JSONArray();}}
    private static synchronized void save(Context c,JSONArray items)throws Exception{AtomicFile f=new AtomicFile(new File(folder(c),"index.json"));FileOutputStream out=null;try{out=f.startWrite();out.write(items.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
    static java.util.List<String> ids(Context c){java.util.List<String> result=new ArrayList<>(Arrays.asList(BUILTIN));JSONArray items=list(c);for(int i=0;i<items.length();i++)result.add(items.optJSONObject(i).optString("id"));return result;}
    static java.util.List<String> names(Context c){java.util.List<String> result=new ArrayList<>(Arrays.asList(NAMES));JSONArray items=list(c);for(int i=0;i<items.length();i++)result.add(items.optJSONObject(i).optString("name"));return result;}
    static String selected(Context c,JSONObject r){String auto=CardStyles.automatic(r);return r.optString("card_background",auto==null?prefs(c).getString("card_background","color"):auto);}
    static boolean valid(String id){return Arrays.asList(BUILTIN).contains(id)||id.matches("[a-f0-9-]{36}");}
    static boolean animated(Context c,JSONObject r){String id=selected(c,r);return id.startsWith("motion:")||id.matches("[a-f0-9-]{36}")&&new File(folder(c),id+".gif").isFile();}
    private static File file(Context c,String id){if(id.equals("wallpaper"))return wallpaper(c);if(!id.matches("[a-f0-9-]{36}"))return null;File gif=new File(folder(c),id+".gif");return gif.isFile()?gif:new File(folder(c),id+".jpg");}
    static synchronized void refreshWallpaper(){wallpaperAt=-10000;}
    private static synchronized File wallpaper(Context c){long now=SystemClock.uptimeMillis();if(wallpaper==null||now-wallpaperAt>10000){wallpaper=WallpaperRules.selected(c);wallpaperAt=now;}return wallpaper;}
    static void paint(Context c,Canvas canvas,RectF area,float radius,JSONObject r,float phase,boolean synchronous,Runnable ready,int maskColor){
        String id=selected(c,r);if(id.equals("color"))return;canvas.save();Path clip=new Path();clip.addRoundRect(area,radius,radius,Path.Direction.CW);canvas.clipPath(clip);boolean drawn=false;Paint p=new Paint(Paint.ANTI_ALIAS_FLAG|Paint.FILTER_BITMAP_FLAG);
        if(id.startsWith("svg:")){Picture vector=vector(c,id.substring(4));if(vector!=null){canvas.save();canvas.translate(area.left,area.top);canvas.scale(area.width()/320,area.height()/180);canvas.drawPicture(vector);canvas.restore();drawn=true;}}
        else if(id.startsWith("motion:")){motion(canvas,area,id,phase,DayEvents.color(r));drawn=true;}
        else{File file=file(c,id);if(file!=null&&file.getName().endsWith(".gif")){drawn=gif(c,canvas,area,file,phase,synchronous,ready);}else if(file!=null&&file.isFile()){boolean blur=prefs(c).getBoolean("blur",true);String key=file.getAbsolutePath()+":"+file.lastModified()+":"+file.length()+":"+blur;Bitmap image=cache.get(key);if(image==null&&synchronous){image=decode(file,blur);if(image!=null)cache.put(key,image);}if(image==null&&!synchronous){synchronized(loading){if(!failed.contains(key)){if(ready!=null)waiters.computeIfAbsent(key,k->new HashSet<>()).add(ready);if(loading.add(key)){worker.execute(()->{Bitmap loaded=decode(file,blur);if(loaded!=null)cache.put(key,loaded);Set<Runnable> callbacks;synchronized(loading){loading.remove(key);if(loaded==null)failed.add(key);callbacks=waiters.remove(key);}if(callbacks!=null)new Handler(Looper.getMainLooper()).post(()->{for(Runnable callback:callbacks)callback.run();});});}}}}if(image!=null){float scale=Math.max(area.width()/image.getWidth(),area.height()/image.getHeight()),w=image.getWidth()*scale,h=image.getHeight()*scale;canvas.drawBitmap(image,null,new RectF(area.centerX()-w/2,area.centerY()-h/2,area.centerX()+w/2,area.centerY()+h/2),p);drawn=true;}}}
        if(drawn&&id.equals("wallpaper")){int opacity=Math.max(0,Math.min(100,prefs(c).getInt("opacity",86)));p.setColor(LiquidGlass.tint(0xfff2f4f8,opacity*178/100));canvas.drawRect(area,p);}canvas.restore();
    }
    private static Bitmap decode(File f,boolean blur){try{Bitmap image=WallpaperImages.decode(f,720);if(image==null||!blur)return image;Bitmap small=Bitmap.createScaledBitmap(image,Math.max(1,image.getWidth()/8),Math.max(1,image.getHeight()/8),true);Bitmap soft=Bitmap.createScaledBitmap(small,image.getWidth(),image.getHeight(),true);if(small!=soft&&small!=image)small.recycle();if(image!=soft)image.recycle();return soft;}catch(RuntimeException|OutOfMemoryError e){return null;}}
    private static synchronized Picture vector(Context c,String name){if(vectors.containsKey(name))return vectors.get(name);if(!Arrays.asList("waves","orbit","geo").contains(name))return null;try(InputStream in=c.getAssets().open("card-backgrounds/"+name+".svg")){XmlPullParser parser=Xml.newPullParser();parser.setInput(in,"UTF-8");Picture result=new Picture();Canvas canvas=result.beginRecording(320,180);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);while(parser.next()!=XmlPullParser.END_DOCUMENT){if(parser.getEventType()!=XmlPullParser.START_TAG)continue;String tag=parser.getName(),fill=parser.getAttributeValue(null,"fill");if(fill==null)continue;p.setColor(Color.parseColor(fill));if(tag.equals("rect"))canvas.drawRect(0,0,Float.parseFloat(parser.getAttributeValue(null,"width")),Float.parseFloat(parser.getAttributeValue(null,"height")),p);else if(tag.equals("path")){Path path=PathParser.createPathFromPathData(parser.getAttributeValue(null,"d"));if(path!=null)canvas.drawPath(path,p);}else if(tag.equals("circle"))canvas.drawCircle(Float.parseFloat(parser.getAttributeValue(null,"cx")),Float.parseFloat(parser.getAttributeValue(null,"cy")),Float.parseFloat(parser.getAttributeValue(null,"r")),p);}result.endRecording();vectors.put(name,result);return result;}catch(Exception e){Diagnostics.record(c,"card-svg",e);return null;}}
    private static void motion(Canvas canvas,RectF a,String id,float phase,int base){Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(id.equals("motion:rainbow")?0xffe1e8f8:id.equals("motion:prism")?0xffe1ddee:id.equals("motion:gold")?0xffefdfb9:id.equals("motion:violet")?0xffdfd0ef:base);canvas.drawRect(a,p);if(id.equals("motion:prism")||id.equals("motion:gold")||id.equals("motion:violet")){float x=a.left-a.width()*.4f+phase*a.width()*1.8f;int[] colors=id.equals("motion:prism")?new int[]{0x00ffffff,0x8894cfd5,0x99c3a1df,0x99e1cc91,0x00ffffff}:id.equals("motion:gold")?new int[]{0x00ffffff,0x99dbb662,0x99ffffff,0x99dbb662,0x00ffffff}:new int[]{0x00ffffff,0x99b791d3,0x99f5f0ff,0x99b791d3,0x00ffffff};p.setShader(new LinearGradient(x-a.width()*.45f,a.top,x+a.width()*.45f,a.bottom,colors,null,Shader.TileMode.CLAMP));canvas.drawRect(a,p);p.setShader(null);}else if(id.equals("motion:aurora")){p.setShader(new LinearGradient(a.left+(float)Math.sin(phase*Math.PI*2)*a.width()*.3f,a.top,a.right+(float)Math.sin(phase*Math.PI*2)*a.width()*.3f,a.bottom,new int[]{0xffa9dbeb,0xffd5b7ed,0xffb8e8d4},null,Shader.TileMode.MIRROR));canvas.drawRect(a,p);}else if(id.equals("motion:ripple")){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(4);p.setColor(0xaaffffff);for(int i=0;i<2;i++)canvas.drawCircle(a.centerX(),a.centerY(),(phase+i/2f)%1*Math.max(a.width(),a.height()),p);}else if(id.equals("motion:rainbow")){for(int i=0;i<5;i++){double angle=(phase+i/5f)*Math.PI*2;float x=a.centerX()+(float)Math.cos(angle)*a.width()*.34f,y=a.centerY()+(float)Math.sin(angle)*a.height()*.30f;int tint=Color.HSVToColor(new float[]{i*72+12,.44f,1});p.setShader(new RadialGradient(x,y,Math.max(a.width(),a.height())*.72f,new int[]{tint,Color.TRANSPARENT},null,Shader.TileMode.CLAMP));canvas.drawRect(a,p);}p.setShader(null);}else if(id.equals("motion:meteors")){for(int i=0;i<3;i++){float t=(phase+i/3f)%1,x=a.left-a.width()*.3f+t*a.width()*1.6f,y=a.top+a.height()*(i*.24f)+t*a.height()*.5f,tail=a.width()*.19f;p.setShader(new LinearGradient(x-tail,y-tail*.3f,x,y,new int[]{0x00ffffff,0xddffffff},null,Shader.TileMode.CLAMP));p.setStrokeWidth(2);canvas.drawLine(x-tail,y-tail*.3f,x,y,p);p.setShader(null);p.setColor(0xeeffffff);canvas.drawCircle(x,y,1.8f,p);}}else{p.setColor(0xccffffff);for(int i=0;i<16;i++){float x=a.left+((i*47%101)/101f)*a.width(),y=a.top+((i*29%97)/97f)*a.height();canvas.drawCircle(x,y,1+(float)Math.sin((phase+i*.1)*Math.PI*2)*.7f,p);}}}
    private static final android.util.LruCache<String,Movie> movies=new android.util.LruCache<>(3);
    private static final Set<String> loadingMovies=new HashSet<>(),failedMovies=new HashSet<>();
    private static final Map<String,Set<Runnable>> movieWaiters=new HashMap<>();
    private static boolean gif(Context c,Canvas canvas,RectF area,File file,float phase,boolean synchronous,Runnable ready){String key=file.getAbsolutePath()+":"+file.lastModified();Movie movie=movies.get(key);if(movie==null&&synchronous){movie=decodeMovie(file);if(movie!=null)movies.put(key,movie);}if(movie==null&&!synchronous){synchronized(loadingMovies){if(failedMovies.contains(key))return false;if(ready!=null)movieWaiters.computeIfAbsent(key,k->new HashSet<>()).add(ready);if(loadingMovies.add(key)){worker.execute(()->{Movie loaded=decodeMovie(file);if(loaded!=null)movies.put(key,loaded);Set<Runnable> callbacks;synchronized(loadingMovies){loadingMovies.remove(key);if(loaded==null)failedMovies.add(key);callbacks=movieWaiters.remove(key);}if(callbacks!=null)new Handler(Looper.getMainLooper()).post(()->{for(Runnable callback:callbacks)callback.run();});});}}return false;}if(movie==null)return false;synchronized(movie){movie.setTime((int)(phase*Math.max(1,movie.duration())));float scale=Math.max(area.width()/movie.width(),area.height()/movie.height());canvas.save();canvas.translate(area.centerX()-movie.width()*scale/2,area.centerY()-movie.height()*scale/2);canvas.scale(scale,scale);movie.draw(canvas,0,0);canvas.restore();}return true;}
    private static Movie decodeMovie(File file){try{return Movie.decodeFile(file.getAbsolutePath());}catch(RuntimeException|OutOfMemoryError failure){return null;}}
    private static boolean isGif(Context c,Uri uri){try(InputStream in=c.getContentResolver().openInputStream(uri)){byte[] header=new byte[6];int size=0,n;while(size<header.length&&(n=in.read(header,size,header.length-size))>0)size+=n;return size==6&&new String(header,java.nio.charset.StandardCharsets.US_ASCII).startsWith("GIF8");}catch(Exception ignored){return false;}}
    private static void importGif(MainActivity a,Uri uri){String[] id={null};a.job(()->{String key=UUID.randomUUID().toString();AtomicFile target=new AtomicFile(new File(folder(a),key+".gif"));FileOutputStream out=null;try(InputStream in=a.getContentResolver().openInputStream(uri)){out=target.startWrite();byte[] buffer=new byte[16384];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);target.finishWrite(out);out=null;Movie movie=decodeMovie(target.getBaseFile());if(movie==null||movie.width()<=0||movie.height()<=0){target.delete();throw new IOException("无法读取 GIF 动画");}JSONArray items=list(a);items.put(new JSONObject().put("id",key).put("name",a.prefs.getString("pending_card_background_name","GIF 背景")).put("format","gif"));save(a,items);id[0]=key;return "已导入 GIF，保留完整动画";}catch(Exception e){if(out!=null)target.failWrite(out);else target.delete();throw e;}},()->finishImport(a,id[0]));}
    static void beginImport(MainActivity a,boolean fromEditor){EditText name=new EditText(a);name.setHint("给背景起个名字");new com.google.android.material.dialog.MaterialAlertDialogBuilder(a).setTitle("导入卡片背景").setView(name).setPositiveButton("选择图片",(d,w)->{String label=name.getText().toString().trim();if(label.isEmpty()){a.message("请先填写背景名称");return;}try{android.content.SharedPreferences.Editor edit=a.prefs.edit().putString("pending_card_background_name",label);if(fromEditor&&a.editorState!=null)edit.putString("pending_card_background_draft",a.editorState.draft().toString());else edit.remove("pending_card_background_draft");edit.commit();a.pickFile(PICK,"image/*");}catch(Exception e){a.message(e.getMessage());}}).setNegativeButton("取消",null).show();}
    static void imported(MainActivity a,Uri uri){if(isGif(a,uri)){importGif(a,uri);return;}ImageTools.crop(a,uri,"裁切卡片背景",cropped->{String[] id={null};a.job(()->{Bitmap image=WallpaperImages.decode(a,cropped,1400);String key=UUID.randomUUID().toString();AtomicFile target=new AtomicFile(new File(folder(a),key+".jpg"));FileOutputStream out=null;try{out=target.startWrite();if(!image.compress(Bitmap.CompressFormat.JPEG,90,out))throw new IOException("无法保存背景图片");target.finishWrite(out);}catch(Exception e){if(out!=null)target.failWrite(out);throw e;}finally{image.recycle();}JSONArray items=list(a);items.put(new JSONObject().put("id",key).put("name",a.prefs.getString("pending_card_background_name","卡片背景")));save(a,items);id[0]=key;return "已保存卡片背景";},()->finishImport(a,id[0]));},()->cancelImport(a));}
    private static void finishImport(MainActivity a,String id){String draft=a.prefs.getString("pending_card_background_draft","");a.prefs.edit().remove("pending_card_background_name").remove("pending_card_background_draft").apply();if(!draft.isEmpty())try{JSONObject record=new JSONObject(draft);CardStyles.apply(record,id);a.edit(record);return;}catch(Exception e){a.message("背景已保存，草稿恢复失败，请从背景库重新选择");}show(a);}
    static void cancelImport(MainActivity a){String draft=a.prefs.getString("pending_card_background_draft","");a.prefs.edit().remove("pending_card_background_name").remove("pending_card_background_draft").apply();if(!draft.isEmpty())try{a.edit(new JSONObject(draft));return;}catch(Exception ignored){}show(a);}
    static void show(MainActivity a){LinearLayout page=a.fullPage("卡片样式",()->new SettingsPanels(a).appearance());page.addView(Ui.text(a,"卡片样式",22,true));page.addView(Ui.help(a,"背景与质感统一选择。可选纯色、哑光、玻璃、渐变、流光、SVG、动态背景或命名图片；同一配置用于应用和单日组件；双日组件保留独立深色样式。图片可命名、裁切；GIF 保留完整动画并居中显示，长按预览可重命名；减少动效会同时暂停两边。"));page.addView(Ui.button(a,"事件默认色系",false,()->PaletteSettings.show(a)));page.addView(Ui.button(a,"导入图片或 GIF",true,()->beginImport(a,false)));java.util.List<String> ids=CardStyles.ids(a),names=CardStyles.names(a);Spinner choice=TaskTypes.spinner(a,page,"默认卡片样式",names);choice.setSelection(Math.max(0,ids.indexOf(CardStyles.current(a,null))));android.widget.FrameLayout sample=new android.widget.FrameLayout(a);sample.setPadding(Ui.dp(a,16),Ui.dp(a,12),Ui.dp(a,16),Ui.dp(a,12));TextView label=Ui.text(a,"今日安排\n09:00–10:00 · 图书馆",16,true);sample.addView(label);page.addView(sample,new LinearLayout.LayoutParams(-1,Ui.dp(a,110)));choice.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,android.view.View v,int i,long n){try{JSONObject record=new JSONObject().put("title","样式预览");CardStyles.apply(record,ids.get(i));sample.setBackground(EventColors.shape(a,record,14));label.setTextColor(EventColors.ink(a,record));}catch(Exception ignored){}}public void onNothingSelected(AdapterView<?> p){}});page.addView(Ui.button(a,"保存默认卡片样式",true,()->{if(!ids.get(choice.getSelectedItemPosition()).equals(CardStyles.current(a,null)))CardStyles.save(a,ids.get(choice.getSelectedItemPosition()));AgendaWidget.refresh(a);a.message("已保存，应用与单日组件使用此样式，双日组件保持原样");}));page.addView(Ui.button(a,"图片模糊与遮罩设置",false,()->new SettingsPanels(a).appearance()));JSONArray images=list(a);for(int i=0;i<images.length();i++){JSONObject item=images.optJSONObject(i);String id=item.optString("id"),name=item.optString("name");TextView preview=Ui.text(a,name,15,true);preview.setPadding(Ui.dp(a,16),Ui.dp(a,16),Ui.dp(a,16),Ui.dp(a,16));try{JSONObject record=new JSONObject().put("title",name);CardStyles.apply(record,id);preview.setBackground(EventColors.shape(a,record,12));preview.setTextColor(EventColors.ink(a,record));}catch(Exception ignored){}LinearLayout.LayoutParams at=new LinearLayout.LayoutParams(-1,Ui.dp(a,80));at.bottomMargin=Ui.dp(a,8);page.addView(preview,at);preview.setOnLongClickListener(v->{rename(a,id,name);return true;});}}
    private static void rename(MainActivity a,String id,String name){EditText value=new EditText(a);value.setText(name);new com.google.android.material.dialog.MaterialAlertDialogBuilder(a).setTitle("重命名背景").setView(value).setPositiveButton("保存",(d,w)->{try{String next=value.getText().toString().trim();if(next.isEmpty())throw new IOException("名称不能为空");JSONArray items=list(a);for(int i=0;i<items.length();i++)if(items.getJSONObject(i).optString("id").equals(id))items.getJSONObject(i).put("name",next);save(a,items);show(a);}catch(Exception e){a.message(e.getMessage());}}).setNegativeButton("取消",null).show();}
}
